-- ============================================================
-- 毕业生就业情况与就业需求调查 数据库脚本 (MSSQL)
-- 表名前缀：zs_
-- 包含：
--   1) 主表 zs_graduate_employment_survey
--   2) 招生类别 zs_category 中插入 graduate_employment_survey
--   3) 字典 zs_dict 中插入：高校(college) / 专业(major) 两类示例数据
-- ============================================================

USE [OA]; -- TODO: 替换为实际数据库名
GO

-- ------------------------------------------------------------
-- 1. 调查主表
-- ------------------------------------------------------------
IF OBJECT_ID(N'dbo.zs_graduate_employment_survey', N'U') IS NOT NULL
    DROP TABLE dbo.zs_graduate_employment_survey;
GO

CREATE TABLE dbo.zs_graduate_employment_survey (
    id                  INT IDENTITY(1,1) NOT NULL PRIMARY KEY,

    -- Q1 学生信息
    student_id          INT             NULL,
    student_no          VARCHAR(50)     NULL,
    student_name        NVARCHAR(50)    NOT NULL,
    class_name          NVARCHAR(100)   NULL,
    id_card             VARCHAR(20)     NULL,

    -- Q2 手机号
    phone               VARCHAR(20)     NOT NULL,

    -- Q3 是否精准服务（1-是 2-否）
    precise_service     VARCHAR(10)     NULL,

    -- Q4 毕业去向 1-11
    destination         VARCHAR(20)     NULL,

    -- Q5 征兵办公室全称
    military_office     NVARCHAR(200)   NULL,

    -- Q6 升学层次（1本科 2专科）
    education_level     VARCHAR(20)     NULL,

    -- Q7 录取高校
    college_code        VARCHAR(50)     NULL,
    college_name        NVARCHAR(200)   NULL,

    -- Q8 录取专业
    major_code          VARCHAR(50)     NULL,
    major_name          NVARCHAR(200)   NULL,

    -- Q9 录取分数
    admission_score     VARCHAR(50)     NULL,

    -- Q10 合同签订情况
    contract_type       VARCHAR(20)     NULL,

    -- Q11 就业渠道
    employment_channel  VARCHAR(20)     NULL,

    -- Q12 工作单位名称
    company_name        NVARCHAR(200)   NULL,

    -- Q13 单位省份/城市
    work_province_city  NVARCHAR(100)   NULL,

    -- Q14 详细地址
    work_address        NVARCHAR(500)   NULL,

    -- Q15 单位性质
    company_nature      VARCHAR(20)     NULL,

    -- Q16 行业
    industry            VARCHAR(20)     NULL,

    -- Q17 工作岗位
    position            VARCHAR(50)     NULL,
    position_name       NVARCHAR(100)   NULL,

    -- Q18 月薪
    monthly_salary      VARCHAR(20)     NULL,

    -- Q19 就业凭证文件URL
    certificate_url     NVARCHAR(500)   NULL,

    -- Q20 满意度
    satisfaction        VARCHAR(20)     NULL,

    -- Q21 是否需要推荐
    need_recommendation VARCHAR(10)     NULL,

    -- Q22 意见或建议
    feedback            NVARCHAR(MAX)   NULL,

    -- 时间戳
    submit_time         DATETIME        NULL DEFAULT GETDATE(),
    create_time         DATETIME        NULL DEFAULT GETDATE(),
    update_time         DATETIME        NULL DEFAULT GETDATE()
);
GO

CREATE INDEX IX_zs_grad_emp_survey_phone   ON dbo.zs_graduate_employment_survey(phone);
CREATE INDEX IX_zs_grad_emp_survey_stu_no  ON dbo.zs_graduate_employment_survey(student_no);
CREATE INDEX IX_zs_grad_emp_survey_destination ON dbo.zs_graduate_employment_survey(destination);
GO

-- ------------------------------------------------------------
-- 2. 在 zs_category 添加调查类别
-- ------------------------------------------------------------
IF NOT EXISTS (SELECT 1 FROM dbo.zs_category WHERE code = 'graduate_employment_survey')
BEGIN
    VALUES ('graduate_employment_survey',
            N'2025届毕业生就业情况与就业需求调查',
            N'2022级毕业生就业情况采集',
            1, 100, GETDATE(), GETDATE());
END
GO

DECLARE @cat_id INT = (SELECT id FROM dbo.zs_category WHERE code = 'graduate_employment_survey');

-- ------------------------------------------------------------
-- 3. 字典：高校列表 (type='college')
--    可按需要追加更多。code 用学校简码或自增编号都可。
-- ------------------------------------------------------------
DELETE FROM dbo.zs_dict WHERE category_id = @cat_id AND type = 'college';

GO

-- ------------------------------------------------------------
-- 4. 字典：专业列表 (type='major')
--    示例几条；完整 744 条专业目录可通过批量脚本导入。
-- ------------------------------------------------------------
DECLARE @cat_id2 INT = (SELECT id FROM dbo.zs_category WHERE code = 'graduate_employment_survey');

DELETE FROM dbo.zs_dict WHERE category_id = @cat_id2 AND type = 'major';

GO


-- ------------------------------------------------------------
-- 5. 字典: 学生列表 (type='student') -- 359 名 2022 级毕业生
-- 数据来源于原 问卷星 调查表 1.html 的姓名下拉选项
-- code   : 学号  | label : 学生姓名
-- remark : 学号-姓名-性别-班级-民族-班主任
-- extra_data: JSON
-- 注意: 多行 VALUES 是 Table Value Constructor，不允许出现子查询，
--       因此用 @cid 变量保存 category_id；DECLARE 与 INSERT 必须
--       处于同一个 batch（不要在它们之间出现 GO）。
-- ------------------------------------------------------------
DECLARE @cid INT = (SELECT id FROM dbo.zs_category WHERE code = 'graduate_employment_survey');

DELETE FROM dbo.zs_dict WHERE category_id = @cid AND type = 'student';


GO

PRINT N'毕业生就业调查表 + 字典 创建完成';
GO
